using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
using UnityEngine.UI;
namespace CafeLife {
 public static class CafeBoulevardChecks {
  public static string Report="";
  static void Check(bool ok,string label){if(!ok)throw new Exception(label);Report+="PASS "+label+"\n";}
  public static void At(CafeGame g,Vector3 p,float yaw=0){g.player.body.enabled=false;g.player.transform.position=p;g.player.transform.rotation=Quaternion.Euler(0,yaw,0);g.player.pitch=0;g.player.view.transform.localRotation=Quaternion.identity;g.player.body.enabled=true;Physics.SyncTransforms();}
  static void Walk(CafeGame g,Vector3 target){for(int i=0;i<1800;i++){Vector3 d=target-g.player.transform.position;d.y=0;if(d.magnitude<.16f)return;Vector3 local=g.player.transform.InverseTransformDirection(d.normalized);g.player.Move(new Vector2(local.x,local.z),.02f);}throw new Exception("Blocked walk to "+target+" at "+g.player.transform.position);}
  public static void Validate(CafeGame g){Report="";g.Continue();At(g,new Vector3(0,.1f,-9.7f));Walk(g,new Vector3(0,0,-21));Walk(g,new Vector3(14,0,-21));Walk(g,new Vector3(14,0,-25));Walk(g,new Vector3(22,0,-25));Walk(g,new Vector3(22,0,-38));Check(g.player.transform.position.y>4,"Walk from cafe across single street and upstairs using CharacterController");Walk(g,new Vector3(18,4.2f,-38));Walk(g,new Vector3(15,4.2f,-30));Check(g.player.transform.position.y>4,"Casino floor accessible from staircase landing");
   var detail=g.world.GetComponentsInChildren<Transform>(true);Check(detail.Count(t=>t.name=="NOIR raf şişesi")==14&&detail.Count(t=>t.name=="NOIR tabure tabanı")==3,"Club bar has scaled shelf bottles and seating");Check(detail.Count(t=>t.name=="Casino kapalı iskambil")==8&&detail.Count(t=>t.name=="Casino ince fiş")==24,"Casino table detail is complete");foreach(var leg in detail.Where(t=>t.name=="Casino masa ayağı"))Check(leg.GetComponent<Renderer>().bounds.max.y<5.1f,"Casino pedestal stays below felt surface");foreach(var card in detail.Where(t=>t.name=="Casino kapalı iskambil"))Check(card.GetComponent<Renderer>().bounds.min.y>5.19f,"Card artwork sits above real casino tabletop");
   var targets=g.world.GetComponentsInChildren<CafeTarget>();foreach(string kind in new[]{"casino","boulevard_market","boulevard_arcade","boulevard_ranking","bench"})Check(targets.Any(t=>t.kind==kind),"Functional street interaction "+kind);
   Check(CafeCasino.Score(new[]{0,13,8})==21&&CafeCasino.Score(new[]{0,5})==17&&CafeCasino.Score(new[]{12,11,4})==25,"Blackjack ace valuation and bust totals");g.data.money=5000;CafeCasinoAccessChecks.Validate(g);Report+=CafeCasinoAccessChecks.Report;g.OpenCasino();var c=g.GetComponent<CafeCasino>();c.StartHand(50);for(int attempt=0;attempt<10&&!c.Active;attempt++)c.StartHand(50);Check(c.Active,"Blackjack starts a playable hand");var deck=(System.Collections.Generic.List<int>)typeof(CafeCasino).GetField("deck",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(c);Check(deck.Concat(c.player).Concat(c.dealer).Distinct().Count()==52,"Shuffled deck has 52 distinct cards");int money=g.data.money;c.StartHand(50);Check(g.data.money==money,"Second bet blocked during an active hand");c.player.Clear();c.player.AddRange(new[]{0,12});c.dealer.Clear();c.dealer.AddRange(new[]{9,6});c.Stand();Check(g.data.money==money+125&&!c.Active,"Natural blackjack pays 3 to 2 and settles once");money=g.data.money;c.Stand();Check(g.data.money==money,"Finished hand cannot pay twice");
   c.StartHand(50);for(int attempt=0;attempt<10&&!c.Active;attempt++)c.StartHand(50);money=g.data.money;c.player.Clear();c.player.AddRange(new[]{9,6});c.dealer.Clear();c.dealer.AddRange(new[]{22,19});c.Stand();Check(g.data.money==money+50,"Blackjack tie refunds stake");money=g.data.money;c.StartHand(-20);Check(g.data.money==money,"Invalid casino bet rejected");
   g.GetComponent<CafeTableBlackjack>().Action("leave");var basketball=g.GetComponent<CafeBasketball>();g.Continue();At(g,new Vector3(-28,.1f,-26));Check(basketball&&basketball.ball&&!basketball.ball.isKinematic,"World basketball has a physical ball");Check(basketball.PickUp()&&!g.Paused&&basketball.Held,"Basket pickup stays in world without a panel");basketball.Throw();Check(!basketball.Held&&!basketball.ball.isKinematic&&basketball.ball.linearVelocity.magnitude>9,"Basket throw releases a moving physical ball");money=g.data.money;var hoop=basketball.hoop;Check(!basketball.CheckBasket(hoop-Vector3.up,hoop+Vector3.up),"Upward hoop crossing cannot score");Check(!basketball.CheckBasket(hoop+Vector3.up+Vector3.right,hoop-Vector3.up+Vector3.right),"Miss outside rim cannot score");Check(basketball.CheckBasket(hoop+Vector3.up*.3f,hoop-Vector3.up*.3f)&&g.data.money==money+50,"Downward basket pays 50 coins");Check(!basketball.CheckBasket(hoop+Vector3.up*.3f,hoop-Vector3.up*.3f)&&g.data.money==money+50,"Same throw cannot pay twice");basketball.ResetBall();Check(basketball.PickUp(),"Basket ball can be retrieved for another shot");basketball.Throw();Check(basketball.CheckBasket(hoop+Vector3.up*.3f,hoop-Vector3.up*.3f)&&g.data.money==money+100,"Another basket pays another 50 with no daily cap");basketball.ResetBall();
   foreach(string section in new[]{"business","supply","upgrade","report","recipes","ranking","settings"}){g.OpenOperations(section);Check(GameObject.Find("Cafe HUD").GetComponentsInChildren<Button>().Length>5,"Designed management section "+section);}int score=CafeStreetActivities.CafeScore(g);g.data.served++;Check(CafeStreetActivities.CafeScore(g)>score,"Cafe ranking responds to service progression");g.Save();var loaded=Economy.Load(g.SavePath);Check(loaded.hundred.basketBest>=2,"Street activity record survives save round trip");At(g,new Vector3(0,.1f,-9.7f));g.Continue();}
 }
}


